/**
 * Mini App `initData` validation, pinned against vectors produced OUTSIDE this
 * codebase.
 *
 * The point of the fixtures below is that they were not generated by the code
 * under test. They come from Python's `hmac`/`hashlib` implementing Telegram's
 * documented two-step derivation:
 *
 *   secret = HMAC_SHA256(key=b"WebAppData", msg=bot_token)
 *   hash   = HMAC_SHA256(key=secret,          msg=data_check_string)
 *
 * If the WebCrypto implementation in src/ui/initdata.ts disagrees about key
 * encoding, field ordering, the newline join, or when to URL-decode, these fail.
 * A fixture minted by the same module would have agreed with a broken module.
 *
 * Vector 3 carries a literal `&` and `%` in the user's first name, which is the
 * case that separates "decode exactly once" from "decode twice".
 */

import test from 'node:test';
import assert from 'node:assert/strict';

import {
  DEFAULT_MAX_AGE_SECONDS,
  DEFAULT_FUTURE_SKEW_SECONDS,
  dataCheckString,
  describeFailure,
  expectedHash,
  validateInitData,
} from '../build/ui/initdata.js';

const TOKEN = '123456:TESTTOKEN';

/**
 * Generated with Python against TOKEN above. `auth_date` is fixed at 1700000000
 * so freshness is exercised through the injected clock, never by waiting.
 */
const V1 = {
  initData:
    'auth_date=1700000000&query_id=AAHdF6IQAAAAAN0Xoha&user=%7B%22id%22%3A42%2C%22first_name%22%3A%22Jen%22%2C%22username%22%3A%22jen%22%7D&hash=1c613f477207d4cd09c735436b2decbfec23a7eb2fa10c5615e589aa9cde707f',
  hash: '1c613f477207d4cd09c735436b2decbfec23a7eb2fa10c5615e589aa9cde707f',
  authDate: 1700000000,
};

/** No `user` field at all: a session from a bot that asked for nothing. */
const V2 = {
  initData:
    'auth_date=1700000001&chat_instance=-123&hash=b0d01db0c3975b44498dd0697ebfc56e6060e04c167f0dd97774f2ea8d36edc2',
  hash: 'b0d01db0c3975b44498dd0697ebfc56e6060e04c167f0dd97774f2ea8d36edc2',
  authDate: 1700000001,
};

/** A `&` and a `%` inside a signed value. Signed over the DECODED form. */
const V3 = {
  initData:
    'auth_date=1700000002&user=%7B%22id%22%3A7%2C%22first_name%22%3A%22A%26B+100%25%22%7D&hash=e66798affd7f06b47b95563a09a4fdf2d65d4a7d002a83fd6e620245b13e787a',
  authDate: 1700000002,
};

const at = (sec) => ({ now: () => sec * 1000 });

test('an independently generated payload verifies, and its user is parsed', async () => {
  const v = await validateInitData(V1.initData, TOKEN, at(V1.authDate + 60));
  assert.equal(v.ok, true, v.ok ? '' : JSON.stringify(v));
  assert.equal(v.authDate, V1.authDate);
  assert.deepEqual(v.user, { id: 42, first_name: 'Jen', username: 'jen' });
  assert.equal(v.queryId, 'AAHdF6IQAAAAAN0Xoha');
  assert.equal(v.ageSeconds, 60);
});

test('a payload with no `user` verifies and yields a null user', async () => {
  const v = await validateInitData(V2.initData, TOKEN, at(V2.authDate + 5));
  assert.equal(v.ok, true);
  assert.equal(v.user, null);
});

test('a value containing & and % verifies: the string is signed decoded, once', async () => {
  const v = await validateInitData(V3.initData, TOKEN, at(V3.authDate + 5));
  assert.equal(v.ok, true, v.ok ? '' : JSON.stringify(v));
  assert.equal(v.user.first_name, 'A&B 100%');
});

test('the expectedHash helper reproduces the independent fixture', async () => {
  assert.equal(await expectedHash(V1.initData, TOKEN), V1.hash);
  assert.equal(await expectedHash(V2.initData, TOKEN), V2.hash);
});

// ── tampering ──────────────────────────────────────────────────────────────

test('changing a signed field after the fact is refused', async () => {
  const tampered = V1.initData.replace('%22id%22%3A42', '%22id%22%3A43');
  assert.notEqual(tampered, V1.initData, 'the fixture must actually have changed');
  const v = await validateInitData(tampered, TOKEN, at(V1.authDate + 5));
  assert.equal(v.ok, false);
  assert.equal(v.reason, 'bad_hash');
});

test('flipping one hex character of the hash is refused', async () => {
  const flipped = V1.initData.slice(0, -1) + (V1.initData.endsWith('f') ? 'e' : 'f');
  const v = await validateInitData(flipped, TOKEN, at(V1.authDate + 5));
  assert.equal(v.ok, false);
  assert.equal(v.reason, 'bad_hash');
});

test('a payload signed for a DIFFERENT bot token is refused', async () => {
  const v = await validateInitData(V1.initData, '999999:OTHERSECRET', at(V1.authDate + 5));
  assert.equal(v.ok, false);
  assert.equal(v.reason, 'bad_hash');
});

test('an upper-case hash still verifies (hex case is not semantic)', async () => {
  const up = V1.initData.replace(V1.hash, V1.hash.toUpperCase());
  const v = await validateInitData(up, TOKEN, at(V1.authDate + 5));
  assert.equal(v.ok, true);
});

// ── fail closed ────────────────────────────────────────────────────────────

test('an unset bot token refuses rather than bypassing', async () => {
  for (const token of [undefined, null, '']) {
    const v = await validateInitData(V1.initData, token, at(V1.authDate + 5));
    assert.equal(v.ok, false);
    assert.equal(v.reason, 'no_bot_token');
  }
});

test('absent or blank initData is refused', async () => {
  for (const raw of [undefined, null, '', '   ']) {
    const v = await validateInitData(raw, TOKEN, at(V1.authDate + 5));
    assert.equal(v.ok, false);
    assert.equal(v.reason, 'missing');
  }
});

test('a payload with no hash is refused', async () => {
  const v = await validateInitData('auth_date=1700000000&user=%7B%7D', TOKEN, at(V1.authDate));
  assert.equal(v.ok, false);
  assert.equal(v.reason, 'no_hash');
});

test('a hash that is not 64 hex characters is refused as no_hash, not bad_hash', async () => {
  const v = await validateInitData('auth_date=1700000000&hash=deadbeef', TOKEN, at(V1.authDate));
  assert.equal(v.ok, false);
  assert.equal(v.reason, 'no_hash');
});

test('a payload carrying ONLY a hash is refused: it would sign the empty string', async () => {
  const empty = await expectedHash('hash=' + V1.hash, TOKEN);
  const v = await validateInitData(`hash=${empty}`, TOKEN, at(V1.authDate));
  assert.equal(v.ok, false);
  assert.equal(v.reason, 'malformed');
});

test('a verified payload with no auth_date is refused', async () => {
  const noDate = 'query_id=AAA&user=%7B%22id%22%3A1%7D';
  const h = await expectedHash(noDate, TOKEN);
  const v = await validateInitData(`${noDate}&hash=${h}`, TOKEN, at(V1.authDate));
  assert.equal(v.ok, false);
  assert.equal(v.reason, 'no_auth_date');
});

test('a verified but stale payload is refused', async () => {
  const fresh = await validateInitData(V1.initData, TOKEN, at(V1.authDate + 60));
  assert.equal(fresh.ok, true, 'the fixture must be valid before it can be stale');

  const stale = await validateInitData(
    V1.initData,
    TOKEN,
    at(V1.authDate + DEFAULT_MAX_AGE_SECONDS + 1),
  );
  assert.equal(stale.ok, false);
  assert.equal(stale.reason, 'stale');
});

test('exactly at the freshness limit is still accepted', async () => {
  const v = await validateInitData(V1.initData, TOKEN, at(V1.authDate + DEFAULT_MAX_AGE_SECONDS));
  assert.equal(v.ok, true);
});

test('a signed payload dated in the future is refused past the skew allowance', async () => {
  const v = await validateInitData(
    V1.initData,
    TOKEN,
    at(V1.authDate - DEFAULT_FUTURE_SKEW_SECONDS - 1),
  );
  assert.equal(v.ok, false);
  assert.equal(v.reason, 'future');
});

test('small clock skew from a phone is tolerated', async () => {
  const v = await validateInitData(V1.initData, TOKEN, at(V1.authDate - 60));
  assert.equal(v.ok, true);
});

test('a malformed user blob does not sink a valid signature', async () => {
  const body = 'auth_date=1700000000&user=not-json';
  const h = await expectedHash(body, TOKEN);
  const v = await validateInitData(`${body}&hash=${h}`, TOKEN, at(V1.authDate + 5));
  assert.equal(v.ok, true);
  assert.equal(v.user, null);
});

// ── shape of the check string ──────────────────────────────────────────────

test('dataCheckString drops `hash`, sorts by key, and joins with newlines', () => {
  const params = new URLSearchParams('user=b&auth_date=1&hash=zzz&query_id=a');
  assert.equal(dataCheckString(params), 'auth_date=1\nquery_id=a\nuser=b');
});

test('a payload with duplicate keys cannot smuggle a second value past the check', async () => {
  // URLSearchParams keeps BOTH; sorting the joined pairs means the signature
  // covers exactly the pairs present, so a duplicate breaks the hash rather than
  // silently shadowing one of them.
  const body = `auth_date=1700000000&auth_date=1700000600&user=x`;
  const h = await expectedHash(body, TOKEN);
  const v = await validateInitData(`${body}&hash=${h}`, TOKEN, at(V1.authDate + 5));
  // It verifies (we signed what we sent) - the point is that the FIRST auth_date
  // is what a naive reader would take, and both are inside the signed string.
  assert.equal(v.ok, true);
  assert.equal(v.authDate, 1700000000);
});

// ── operator-facing text ───────────────────────────────────────────────────

test('every failure reason maps to a non-empty operator sentence', () => {
  for (const r of [
    'no_bot_token',
    'missing',
    'malformed',
    'no_hash',
    'bad_hash',
    'no_auth_date',
    'stale',
    'future',
  ]) {
    const s = describeFailure(r);
    assert.equal(typeof s, 'string');
    assert.ok(s.length > 20, `${r} -> ${s}`);
  }
});

test('a denial never echoes the presented secret or the hash', async () => {
  const v = await validateInitData(V1.initData, 'wrong-token', at(V1.authDate));
  assert.equal(v.ok, false);
  const text = JSON.stringify(v) + describeFailure(v.reason);
  assert.ok(!text.includes(V1.hash), 'the response must not carry the expected hash');
  assert.ok(!text.includes('wrong-token'), 'the response must not carry the token');
});
